<article class="blog-article">
 <header class="article-header section"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?=e(site_url())?>"><?=e(t('nav.home'))?></a><span>/</span><a href="<?=e(\App\Services\Seo::localizedUrl('/blog',$lang))?>"><?=e(t('blog.title'))?></a><span>/</span><span><?=e(field($post,'title'))?></span></nav><p class="eyebrow"><?=e(field($post,'category'))?></p><h1><?=e(field($post,'title'))?></h1><p class="article-excerpt"><?=e(field($post,'excerpt'))?></p><div class="article-meta"><?php if(!empty($post['author'])):?><span><?=e(field($post,'author'))?></span><span>·</span><?php endif;?><time datetime="<?=e(($post['publish_at']??'')?:$post['_created_at'])?>"><?=e(date('d.m.Y',strtotime(($post['publish_at']??'')?:$post['_created_at'])))?></time><span>· <?=max(1,(int)ceil(count(preg_split('/\s+/u',strip_tags($article['html']),-1,PREG_SPLIT_NO_EMPTY))/200))?> <?=e(t('blog.minutes'))?></span></div><?php if($preview):?><p class="notice"><?=e(t('blog.preview'))?></p><?php endif;?></header>
 <div class="article-cover"><img fetchpriority="high" decoding="async" src="<?=e($post['cover'])?>" alt="<?=e(field($post,'cover_alt')?:field($post,'title'))?>"></div>
 <div class="article-layout section"><?php if($article['toc']):?><aside class="article-toc"><p class="eyebrow"><?=e(t('blog.contents'))?></p><nav><?php foreach($article['toc'] as $heading):?><a class="<?=e($heading['level'])?>" href="#<?=e($heading['id'])?>"><?=e($heading['label'])?></a><?php endforeach;?></nav></aside><?php endif;?><div class="article-body"><?=$article['html']?></div></div>
 <?php $related=array_slice(array_values(array_filter(records('post'),fn($r)=>$r['id']!==$post['id']&&\App\Services\Seo::visible($r)&&($r['category']??'')===($post['category']??''))),0,3);if($related):?><section class="related-posts section"><p class="eyebrow"><?=e(t('blog.related'))?></p><div class="related-grid"><?php foreach($related as $r):?><a href="<?=e(site_url(['post'=>$r['slug']]))?>"><?=e(field($r,'title'))?> ↗</a><?php endforeach;?></div></section><?php endif;?>
</article>
